import re,subprocess,pathlib
missing={}
found=0
for p in sorted(pathlib.Path("docs/audits").glob("audit-0[1-9]-*.md")):
    for h in sorted(set(re.findall(r"(?<![0-9a-f])[0-9a-f]{40}(?![0-9a-f])", p.read_text()))):
        ok = subprocess.run(["git","cat-file","-e",h+"^{commit}"],capture_output=True).returncode==0
        if ok: found+=1
        else:
            spec = subprocess.run(["git","-C","../mhfe_spec","cat-file","-e",h+"^{commit}"],capture_output=True).returncode==0
            if not spec: missing.setdefault(p.name,[]).append(h)
print("40-hex commit names found in mhfe:", found)
for k,v in missing.items(): print("not a commit of mhfe or mhfe_spec:", k, len(v), v[:6])
